/**
 * test-pdf-chatgpt-poche.ts — step Q.2: tests/fixtures/pdf/plan-chatgpt-poche.pdf, a three-bedroom
 * house in poche (A2, 1:50) generated by ChatGPT, NOT a real CAD export, read end to end and compared
 * with its trimmed truth (plan-chatgpt-poche.truth.json, millimetres, y north; the truth's own
 * discrepancies are listed in it). This file was used to FIND the Q.2 classes; none of them is proven
 * here (the holdout rule: each is proven on its own synthetic fixture, scripts/test-pdf-poche.ts).
 * The expectations are HONEST: what is read now and what is still wrong, each asserted as it is so a
 * change shows, and printed.
 *
 * Read correctly: all 18 walls' centre lines and thicknesses (the 45° one included), read from the
 * PDF alone (rule 8b) with ONE free end left, the corridor wall's west end, where the drawing leaves a
 * 25 mm slot; five windows; D1–D5 with hinge jamb and side, D6 as a double door; 12 dimensions, scale
 * good, none flagged; the title block dropped on its text and reported.
 * Still wrong: W4 is not read (a partition ends inside it; reported by name); D7 (sliding, drawn as two
 * concentric lines, not staggered panels) and OP1 (an open passage) are unclassified doors; Dining and
 * Kitchen are one room (no wall drawn between them), and Living and Corridor one room (the slot).
 *
 * Run: npx tsx scripts/test-pdf-chatgpt-poche.ts
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { analysePdfPage } from "../src/lib/pdf/analysePdf";
import { dimensionRows } from "../src/lib/pdf/dimensions";
import { buildPdfPlan, conflictText } from "../src/lib/pdf/snap";
import { wallLength } from "../src/lib/plan/geometry";
import { deriveRooms } from "../src/lib/plan/rooms";
import { validatePlan } from "../src/lib/plan/validate";
import type { Vec2 } from "../src/types/plan";
import { openNode, pdfjs, renderNode } from "./pdf-node";

const DIR = join(__dirname, "../tests/fixtures/pdf");
type P = [number, number];
const truth: {
  walls: { id: string; a: P; b: P; thickness: number }[];
  doors: { id: string; a: P; b: P; width: number; style: string; hinge?: P; side?: P }[];
  windows: { id: string; a: P; b: P; width: number }[];
  passages: { id: string; a: P; b: P; width: number }[];
  rooms: { name: string; min: P; max: P }[];
  dimensions: { id: string; value: number }[];
} = JSON.parse(readFileSync(join(DIR, "plan-chatgpt-poche.truth.json"), "utf8"));
const HALF_MM = 0.5; // millimetres here
const K = 0.0566929133858268; // points per truth millimetre (1:50)
const near = (p: P, q: P, tol = HALF_MM) => Math.hypot(p[0] - q[0], p[1] - q[1]) <= tol;
/** Distance from p to the line through a and b (millimetres). */
const toLine = (p: P, a: P, b: P) => Math.abs((b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])) / Math.hypot(b[0] - a[0], b[1] - a[1]);

async function main() {
  const doc = await openNode(new Uint8Array(readFileSync(join(DIR, "plan-chatgpt-poche.pdf"))));
  const t0 = Date.now();
  const r = await analysePdfPage(pdfjs, await doc.getPage(1), { pageCount: 1, render: renderNode, ocr: async () => ({ labels: [], words: [], error: null, rereads: [] }) });
  await doc.loadingTask.destroy();
  const pxPerM = r.analysis.scale.pxPerM!;
  const b = buildPdfPlan(r.analysis, r.pdf, { pxPerM, source: "pdf" });
  const ms = Date.now() - t0;
  const c = b.coverage;
  // Plan metres -> the truth's millimetres (through page points).
  const mm = (p: Vec2): P => {
    const [xp, yp] = [(p.x + c.origin.x) / c.mPerPt, (p.y + c.origin.y) / c.mPerPt];
    return [(xp - 310) / K, (875.551181 - yp) / K];
  };

  // ------------------------------------------------------------ scale and dimensions
  const s = r.pdf.scale!;
  assert.equal(s.confidence, "good", `scale good (${s.reason})`);
  assert.ok(Math.abs(s.mPerPt! / s.title!.mPerPt - 1) < 0.0001, "the printed dimensions agree with the title block's 1:50");
  const rows = dimensionRows(s.matches, s.mPerPt!);
  assert.deepEqual(rows.map((x) => Math.round(x.printedM * 1000)).sort((p, q) => p - q), truth.dimensions.map((d) => d.value).sort((p, q) => p - q), "every printed dimension is a row");
  assert.ok(rows.every((x) => x.status === "ok"), `every dimension row OK (the 2000 on DIM03's line measured on its own: ${rows.filter((x) => x.status !== "ok").map((x) => x.text)})`);

  // ------------------------------------------------------------ walls
  assert.ok(c.pdfOnly && c.traced === 0 && c.exact === b.plan.walls.length, `walls read entirely from the PDF: ${c.exact} of ${c.walls}`);
  const built = b.plan.walls.map((w) => ({ a: mm(w.a), b: mm(w.b), t: w.thickness * 1000 }));
  // A truth wall is built when walls on its centre line, at its thickness, cover it end to end
  // (along the line; the truth ends some interior walls at faces, Atrium at centre lines).
  const onLine = (w: { a: P; b: P; t: number }, tw: (typeof truth.walls)[number]) => Math.abs(w.t - tw.thickness) <= HALF_MM && toLine(w.a, tw.a, tw.b) <= HALF_MM && toLine(w.b, tw.a, tw.b) <= HALF_MM;
  const short: string[] = [];
  for (const tw of truth.walls) {
    const L = Math.hypot(tw.b[0] - tw.a[0], tw.b[1] - tw.a[1]);
    const u: P = [(tw.b[0] - tw.a[0]) / L, (tw.b[1] - tw.a[1]) / L];
    const at = (p: P) => (p[0] - tw.a[0]) * u[0] + (p[1] - tw.a[1]) * u[1];
    const spans = built.filter((w) => onLine(w, tw)).map((w) => [at(w.a), at(w.b)].sort((p, q) => p - q)).sort((p, q) => p[0] - q[0]);
    assert.ok(spans.length > 0 && spans[0][0] <= HALF_MM, `${tw.id}: its centre line, ${tw.thickness} mm thick, is built from its start`);
    let reach = spans[0][1];
    for (const [p, q] of spans) if (p <= reach + HALF_MM) reach = Math.max(reach, q);
    if (reach < L - HALF_MM) short.push(`${tw.id} ${(L - reach).toFixed(1)}`);
  }
  // Where the truth's end convention differs from the drawing's joints (its discrepancies): the
  // living/dining wall's truth end is 50 mm past the corridor wall's centre line, where Atrium joins
  // it, and the diagonal's 1.47 mm short of the north wall's, where Atrium runs it.
  const allowed = ["INT_LIVING_DINING 50.0", "INT_MASTER_DIAGONAL 1.5"];
  assert.ok(short.every((x) => allowed.includes(x)), `every truth wall built end to end but for the truth's own end convention (${short})`);
  const offLine = built.filter((w) => !truth.walls.some((tw) => onLine(w, tw)));
  assert.deepEqual(offLine, [], "no wall off the truth's lines (title block, furniture, dimensions, window lines all left out)");
  // One free end remains, and it is the corridor wall's west end, where the drawing leaves a 25 mm slot.
  assert.equal(c.freeEnds.length, 1, `one free end (${c.freeEnds.map((p) => mm(p).map((v) => v.toFixed(0)).join(", "))})`);
  assert.ok(near(mm(c.freeEnds[0]), [4250, 3600], HALF_MM), `the free end is INT_CORRIDOR_SOUTH's west end, on INT_BATH_EAST's line (${mm(c.freeEnds[0])})`);
  assert.ok(c.detached.some((x) => x.dropped) && c.detached.every((x) => x.dropped), `the title block dropped on its text and reported (${c.detached.map((x) => x.why)})`);

  // ------------------------------------------------------------ openings
  const ops = b.plan.openings.map((o) => {
    const w = b.plan.walls.find((x) => x.id === o.wallId)!;
    const L = wallLength(w);
    const at = (k: number): P => mm({ x: w.a.x + ((w.b.x - w.a.x) / L) * k, y: w.a.y + ((w.b.y - w.a.y) / L) * k });
    const [ja, jb] = [at(o.offset - o.width / 2), at(o.offset + o.width / 2)];
    // The leaf's side in the truth's frame: the plan's (-dy, dx) normal for "left" (plan y down, truth y up).
    const n = { x: -(w.b.y - w.a.y) / L, y: (w.b.x - w.a.x) / L };
    const side: P = o.swing === "left" ? [n.x, -n.y] : [-n.x, n.y];
    return { o, ja, jb, hinge: o.hinge === "b" ? jb : ja, side };
  });
  const find = (a: P, bb: P) => ops.find((x) => (near(x.ja, a) && near(x.jb, bb)) || (near(x.ja, bb) && near(x.jb, a)));
  const singles = truth.doors.filter((d) => d.style === "single hinged");
  for (const d of singles) {
    const x = find(d.a, d.b);
    assert.ok(x && x.o.kind === "door" && x.o.provenance === "vector", `${d.id}: a door read from the PDF, jambs within 0.5 mm`);
    assert.ok(near(x!.hinge, d.hinge!), `${d.id}: hung on the truth's hinge jamb`);
    assert.ok(x!.side[0] * d.side![0] + x!.side[1] * d.side![1] > 0.99, `${d.id}: opens to the truth's side`);
  }
  const double = truth.doors.find((d) => d.style === "double hinged")!;
  const dd = find(double.a, double.b);
  assert.ok(dd && dd.o.kind === "door" && dd.side[0] * double.side![0] + dd.side[1] * double.side![1] > 0.99, `${double.id}: the double door read, opening to the truth's side`);
  // Still wrong (honest): the sliding door is drawn as two concentric lines (94% and 77% of the gap),
  // not CAD's staggered panels, and the passage has no leaf; both are kept as unclassified doors.
  const sliding = truth.doors.find((d) => d.style === "sliding")!;
  for (const x of [sliding, ...truth.passages]) {
    const hit = find(x.a, x.b);
    assert.ok(hit && hit.o.kind === "door" && c.unclassifiedOpenings.some((u) => u.id === hit.o.id), `${x.id}: read at its exact jambs, as an unclassified door`);
  }
  const W4 = truth.windows.find((w) => w.id === "W4_NORTH_BEDROOM_2")!;
  for (const w of truth.windows.filter((x) => x !== W4)) {
    const x = find(w.a, w.b);
    assert.ok(x && x.o.kind === "window" && x.o.provenance === "vector", `${w.id}: a window read from the PDF, jambs within 0.5 mm`);
  }
  // Still wrong (honest, the drawing's fault): INT_BEDROOM_2_3 ends inside W4, so W4 is not read, and said.
  assert.ok(!find(W4.a, W4.b) && c.conflicts.length === 1 && c.conflicts[0].kind === "window" && Math.abs(c.conflicts[0].width * 1000 - W4.width) < HALF_MM, `W4: not read, reported (${c.conflicts.map((x, i) => conflictText(x, i))})`);
  assert.equal(b.plan.openings.length, truth.doors.length + truth.windows.length + truth.passages.length - 1, "no other opening");

  // ------------------------------------------------------------ rooms
  const problems = validatePlan(b.plan);
  assert.equal(problems.length, 1, `the validator lists only the corridor wall's free end (${problems})`);
  const rooms = deriveRooms(b.plan);
  const area = (name: string) => {
    const tr = truth.rooms.find((x) => x.name === name)!;
    return ((tr.max[0] - tr.min[0]) * (tr.max[1] - tr.min[1])) / 1e6;
  };
  for (const name of ["Bathroom 1", "Bathroom 2", "Utility"]) {
    const room = rooms.find((x) => x.name === name);
    assert.ok(room && Math.abs(room.area - area(name)) < 1e-3, `${name}: named, ${room?.area.toFixed(4)} m² against the truth's ${area(name).toFixed(4)} m²`);
  }
  // Bedroom 3 against the drawn faces: the truth's bounds assume a 100 mm partition, the poche is 150 mm (a discrepancy).
  const bed3 = rooms.find((x) => x.name === "Bedroom 3");
  assert.ok(bed3 && Math.abs(bed3.area - 2.525 * 2.5) < 1e-3, `Bedroom 3: named, ${bed3?.area.toFixed(4)} m², 2525 × 2500 mm as drawn (the truth says 2550)`);
  for (const name of ["Master Bedroom", "Bedroom 2"]) assert.ok(rooms.some((x) => x.name === name), `${name}: closed by the 45° wall and named (${rooms.map((x) => x.name)})`);
  // Still wrong, and right by the drawing: no wall between Dining and Kitchen, and the 25 mm slot.
  assert.ok(rooms.some((x) => /Dining/.test(x.name) && /Kitchen/.test(x.name)), `Dining and Kitchen are one room (${rooms.map((x) => x.name)})`);
  assert.ok(rooms.some((x) => /Living/.test(x.name) && /Corridor/.test(x.name)), `Living and Corridor are one room (${rooms.map((x) => x.name)})`);

  console.log(
    `plan-chatgpt-poche.pdf (ChatGPT-generated, not real CAD): walls ${c.exact} exact, ${c.traced} traced, read entirely from the PDF, ${c.freeEnds.length} free end; ` +
      `openings ${c.openings.exact} exact of ${c.openings.total}, ${c.openings.traced} traced, 2 wrong type (D7 sliding and OP1, unclassified), W4 not read (${conflictText(c.conflicts[0], 0, "m")}); ` +
      `doors ${singles.length}/${singles.length} single with hinge and side right, the double door right; windows ${truth.windows.length - 1}/${truth.windows.length}; ` +
      `dimensions ${rows.length} read, ${rows.filter((x) => x.status !== "ok").length} flagged; ` +
      `rooms closed ${rooms.length} (${rooms.map((x) => `${x.name} ${x.area.toFixed(2)} m²`).join(", ")}); title block dropped; ${(ms / 1000).toFixed(1)} s`,
  );
  console.log("still wrong: W4 (a partition ends inside it); D7 and OP1 unclassified; Dining + Kitchen and Living + Corridor one room each (the drawing); heights are defaults");
  console.log("OK");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
